class Solution {
  public int bestRotation(int[] nums) {
    int n = nums.length;
    int[] diff = new int[n + 1];
    for (int i = 0; i < n; i++) {
      int value = nums[i];
      int start = (i - value + 1 + n) % n;
      int end = (i + 1) % n;
      diff[start]++;
      diff[end]--;
      if (start > end) diff[0]++;
    }
    int score = 0, best = 0, bestScore = -1;
    for (int k = 0; k < n; k++) {
      score += diff[k];
      int valid = n - score;
      if (valid > bestScore) {
        bestScore = valid;
        best = k;
      }
    }
    return best;
  }
}
